88	    public Object parseJsonBody(Object body) {
89	        try {
90	            if (body instanceof String) {
91	                // Setting the requestBody to an empty byte array here
92	                // since the an empty string causes issues with a signed request.
93	                // If the content of the SignableRequest is null, the query string parameters
94	                // will be encoded and used as the contentSha256 segment of the canonical request string.
95	                // This causes a SignatureMatch Error for signed urls like those generated by AWS S3.
96	                // More detail here - https://github.com/aws/aws-sdk-java/issues/2205
97	                if ("" == body) {
98	                    return new byte[0];
99	                }
100	                Object objectFromJson = objectFromJson((String) body);
101	                if (objectFromJson != null) {
102	                    body = objectFromJson;
103	                }
104	            }
105	        } catch (JsonSyntaxException | ParseException e) {
106	            throw new AppsmithPluginException(
107	                    AppsmithPluginError.PLUGIN_JSON_PARSE_ERROR, body, "Malformed JSON: " + e.getMessage());
108	        }
109	        return body;
110	    }
