77	
78	        private final Consumer<T> consumer;
79	        private final List<MediaType> mediaTypes;
80	
81	        WriteToConsumer(Consumer<T> consumer) {
82	            this.consumer = consumer;
83	            this.mediaTypes = Collections.singletonList(MediaType.ALL);
84	        }
85	
86	        @Override
87	        public List<MediaType> getWritableMediaTypes() {
88	            return mediaTypes;
89	        }
90	
91	        @Override
92	        public boolean canWrite(ResolvableType elementType, MediaType mediaType) {
93	            return true;
94	        }
95	
96	        @Override
97	        public Mono<Void> write(
98	                Publisher<? extends T> inputStream,
99	                ResolvableType elementType,
100	                MediaType mediaType,
101	                ReactiveHttpOutputMessage message,
